 private void clear(){authenticationFlow=false;loadGeneration++;if(browser!=null&&browser.getParent()!=null){browser.stopLoading();((android.view.ViewGroup)browser.getParent()).removeView(browser);}content.removeAllViews();titleInput=bodyInput=targetInput=delayInput=null;accountDetails=null;executionDetails=null;}
