 private void bind(Task t){if(session.state!=SessionInfo.State.LOGGED_IN||session.uid.isEmpty())throw new IllegalStateException("请先登录并确认论坛账户，再创建发布任务");t.accountId=session.uid;t.accountName=session.nickname;}
 private void pastePage(){if(busy||(engine!=null&&engine.busy())){notice("请先暂停发布");return;}clear();tab="paste";LinearLayout l=scroll();LinearLayout c=card(l);c.addView(text("复制粘贴 · 多条发布",22,INK));c.addView(text(draftReply?"每段是一条回复；独立一行 === 分隔。回复目标沿用写帖页。":"每段第一行是标题，其余为正文；独立一行 === 分隔多帖。",15,MUTED));EditText box=input(c,"粘贴区（不会自动读取剪贴板）","",10);row(c,button("从剪贴板粘贴",()->{android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);ClipData clip=cm.getPrimaryClip();if(clip!=null&&clip.getItemCount()>0)box.setText(clip.getItemAt(0).coerceToText(this));}),button("预览分隔结果",()->{try{List<Task> list=BulkPaste.parse(box.getText().toString(),draftReply,draftTarget.trim());for(Task t:list){t.message=withSignature(t.message);t.validate();bind(t);}previewPaste(list);}catch(Exception e){notice(e.getMessage());}}));c.addView(button("添加并发送",()->{try{List<Task> list=BulkPaste.parse(box.getText().toString(),draftReply,draftTarget.trim());for(Task t:list){t.message=withSignature(t.message);t.validate();bind(t);}addAndSend(list);}catch(Exception e){notice(e.getMessage());}}));l.addView(text("可以直接添加发送；分隔预览为可选，不再逐条审核。",13,MUTED));l.addView(button("返回写帖",this::compose));}
 private void addAndSend(List<Task> tasks)throws Exception{if(engine.busy())throw new IllegalStateException("发布进行中，请先等待或暂停");if(session.state!=SessionInfo.State.LOGGED_IN)throw new IllegalStateException("请先确认论坛账户已登录");for(Task t:tasks){if(!t.accountId.equals(session.uid))throw new IllegalStateException("任务与当前账户不一致");t.approve();t.note="已添加到发送队列，按发布规则执行";}store.addAll(tasks);if(!prefs.edit().putBoolean("queueEnabled",true).commit())throw new IOException("任务已加入，但启动开关保存失败，请在队列手动开始");running=true;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);queue();status.setText("已添加，正在按规则启动发送队列");tick();}
 private void previewPaste(List<Task> list){clear();tab="paste-preview";LinearLayout l=scroll();l.addView(text("分隔预览 · "+list.size()+" 条 · "+session.nickname,20,INK));for(int n=0;n<list.size();n++){Task t=list.get(n);LinearLayout c=card(l);c.addView(text((n+1)+". "+(t.reply?"回复 "+t.tid:t.title),18,INK));TextView body=text(t.message,16,INK);body.setTextIsSelectable(true);c.addView(body);}row(l,button("重新粘贴",this::pastePage),button("确认添加并发送",()->{try{if(session.state!=SessionInfo.State.LOGGED_IN||!list.get(0).accountId.equals(session.uid))throw new IllegalStateException("账户已变化，请重新预览");addAndSend(list);}catch(Exception e){notice(e.getMessage());}}));}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=EXPORT||result!=RESULT_OK||data==null||data.getData()==null)return;try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException("无法创建文件");out.write(exportQueue().getBytes(StandardCharsets.UTF_8));notice("记录已导出，不含会话");}catch(Exception e){notice(e.getMessage());}}
 private String exportQueue()throws Exception{JSONArray a=new JSONArray();for(Task t:store.tasks)a.put(new JSONObject().put("id",t.id).put("kind",t.reply?"reply":"thread").put("fid","152").put("tid",t.tid).put("subject",t.title).put("message",t.message).put("at",t.at).put("latest",t.latest).put("plannedAt",t.plannedAt).put("accountId",t.accountId).put("accountName",t.accountName).put("typeId",t.typeId).put("status",t.state==Task.State.DONE?"done":t.state.name().toLowerCase(Locale.ROOT)).put("note",t.note).put("receipt",t.receipt));return new JSONObject().put("edition","G").put("format","my0511-lite-queue-v1").put("queue",a).toString(2);}
 private boolean persist(){try{store.save();return true;}catch(Exception e){running=false;prefs.edit().putBoolean("queueEnabled",false).commit();if(engine!=null)engine.cancel(null,"任务存储失败，停止发布");notice("无法保存任务状态，已停止发布："+e.getMessage());return false;}}
 private void queue(){clear();tab="queue";LinearLayout activityCard=card(content);activityCard.addView(text("执行状态",17,INK));executionDetails=text(engine.progress(),15,GREEN);activityCard.addView(executionDetails);executionDetails.setOnClickListener(v->logs());if(engine.busy()){ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setIndeterminate(true);activityCard.addView(bar,new LinearLayout.LayoutParams(-1,dp(5)));}shownRevision=engine.revision();row(content,button((running||engine.busy())?"暂停执行":"开始执行",()->{if(running||engine.busy())pause("你已暂停队列");else startQueue();queue();}),button("粘贴多条内容",this::pastePage));LinearLayout l=scroll();l.addView(text("只执行当前账户的发送任务 · 结果不确定时不重发",13,MUTED));if(store.tasks.isEmpty())l.addView(text("队列为空。可以写一帖，或粘贴多条内容。",18,INK));for(Task t:new ArrayList<>(store.tasks)){LinearLayout c=card(l);c.addView(text(t.label()+" · "+(t.reply?"回复 "+t.tid:t.title),18,INK));c.addView(text(t.message.length()>180?t.message.substring(0,180)+"…":t.message,15,INK));c.addView(text("账户："+(t.accountName.isEmpty()?"未绑定，点击下方绑定并重审":t.accountName)+" · "+t.source+(t.at>0?" · 最早 "+java.time.Instant.ofEpochMilli(t.at).atZone(PublishRules.ZONE).toLocalDateTime():"")+(t.latest>0?" · 最晚 "+java.time.Instant.ofEpochMilli(t.latest).atZone(PublishRules.ZONE).toLocalDateTime():"")+(t.plannedAt>0?"\n计划不早于："+java.time.Instant.ofEpochMilli(t.plannedAt).atZone(PublishRules.ZONE).toLocalDateTime():"")+"\n"+t.note,12,MUTED));c.addView(button("查看全文",()->new AlertDialog.Builder(this).setTitle(t.reply?"回复 "+t.tid:t.title).setMessage(t.message).setPositiveButton("关闭",null).show()));
  if(t.accountId.isEmpty()&&(t.state==Task.State.DRAFT||t.state==Task.State.READY||t.state==Task.State.WAITING_HUMAN))c.addView(button("绑定当前账户并加入队列",()->new AlertDialog.Builder(this).setTitle("绑定这条旧版任务？").setMessage("请先确认这条内容没有手动发出。确认绑定后直接进入发送队列。\n当前账户："+session.nickname).setNegativeButton("取消",null).setPositiveButton("确认未发出，绑定",(d,w)->{try{if(running||engine.busy())throw new IllegalStateException("请先暂停执行");bind(t);t.state=Task.State.READY;t.note="已确认未提交并绑定当前账户，等待发送";if(persist())queue();}catch(Exception e){notice(e.getMessage());}}).show()));if(t.state==Task.State.READY&&t.accountId.equals(session.uid))c.addView(button("立即执行此条（仍检查限额）",()->sendOne(t)));if(t.state==Task.State.DRAFT)c.addView(button("加入队列并发送",()->{try{if(session.state!=SessionInfo.State.LOGGED_IN||!t.accountId.equals(session.uid))throw new IllegalStateException("请先切换到任务绑定账户");t.approve();t.note="已添加到发送队列";if(!persist())return;prefs.edit().putBoolean("queueEnabled",true).commit();running=true;queue();tick();}catch(Exception e){notice(e.getMessage());}}));
  if(t.state==Task.State.WAITING_HUMAN)c.addView(button("打开官方表单处理验证",()->openBrowser(ForumPolicy.post(t))));if(t.state==Task.State.NEEDS_REVIEW)c.addView(button("到论坛核实结果",()->openBrowser(t.reply?ForumPolicy.thread(t.tid,1):ForumPolicy.board(1))));if(t.state==Task.State.WAITING_HUMAN)c.addView(button("确认尚未发出，重新排队",()->new AlertDialog.Builder(this).setMessage("请先确认论坛没有出现这条内容。若你已手动发表，请勿重排。\n"+t.note).setNegativeButton("取消",null).setPositiveButton("确认未发表",(d,w)->{try{if(!t.accountId.equals(session.uid)||session.state!=SessionInfo.State.LOGGED_IN)throw new IllegalStateException("请先切换到任务绑定的账户");t.approve();if(persist())queue();}catch(Exception e){notice(e.getMessage());}}).show()));
  if(t.state==Task.State.NEEDS_REVIEW){row(c,button("核实：已经发出",()->review(t,true)),button("核实：没有发出",()->review(t,false)));}
  if(!t.locked()&&t.state!=Task.State.DONE&&t.state!=Task.State.FAILED)c.addView(button("时间范围 / 分类",()->timing(t)));if(!t.receipt.isEmpty())c.addView(text("发布回执："+t.receipt,12,GREEN));
  if(!t.locked()&&t.state!=Task.State.WAITING_HUMAN)c.addView(button("删除此任务",()->new AlertDialog.Builder(this).setMessage("删除这条本地任务？论坛内容不会被删除。").setNegativeButton("保留",null).setPositiveButton("删除",(d,w)->{if(t.locked()||busy){notice("任务正在执行或待核实，不能删除");return;}store.tasks.remove(t);if(persist())queue();}).show()));
 }
 }
 private void review(Task t,boolean posted){new AlertDialog.Builder(this).setTitle("记录人工核实结果").setMessage(posted?"确认已在论坛找到这条内容？":"确认论坛没有出现这条内容？本次只标记停止；如需再发，请重新写草稿。").setNegativeButton("取消",null).setPositiveButton("确认",(d,w)->{t.state=posted?Task.State.DONE:Task.State.FAILED;t.note=posted?"用户核实：已经发表":"用户核实：未发表，已停止";if(persist())queue();}).show();}
