  LinearLayout privacy=card(l);privacy.addView(text("隐私与连接",20,INK));privacy.addView(text("权限：联网、查询网络状态、接收系统重启（仅后台调度使用）。\n无定位、通讯录、电话、麦克风、相机、存储读取权限；无广告、统计、推送 SDK。阅读页不执行论坛脚本；图片逐张确认后才下载。\n登录/发帖页按请求白名单限制为论坛、登录站及静态资源主机的 HTTPS 请求；验证码或登录页若依赖其他服务，可能无法使用。不会为兼容性放开全部第三方连接。\n粘贴内容保存在应用私有目录，卸载时删除；不备份登录状态。",15,INK));privacy.addView(button("登录 / 处理验证",()->openBrowser(ForumPolicy.LOGIN)));privacy.addView(button("退出当前登录",this::confirmLogout));
  LinearLayout local=card(l);local.addView(text("粘贴与恢复",20,INK));local.addView(text("只在你点击粘贴时读取剪贴板，不自动扫描或采集。使用独立一行 === 分隔多条内容。\n应用离开前台、进程中断或出现验证时暂停；提交之后不确定的任务必须人工核实。后台开关关闭时不会后台发布；不确定结果始终不自动重发。\n每日统计按北京时间计数；最早发布时间显示为北京时间。",15,INK));local.addView(button("导出任务记录",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"my0511-lite-G-queue.json");startActivityForResult(i,EXPORT);}));l.addView(text("0.2.2-G 测试版 · 尚未完成真机登录及真实发布验证",13,MUTED));
